from itertools import islice

class SearchArray:
    def __init__(self,
                 postings,
                 doc_len: int = 0,
                 posns: Optional[dict] = None,
                 encoded=False):
        self.postings = postings
        self.doc_len = doc_len
        self.posns = posns
        self.encoded = encoded

    @classmethod
    def term_dict(cls, postings):
        term_dict = defaultdict(list)
        for doc_id, positions in postings.items():
            for pos in positions:
                term_dict[pos].append(doc_id)
        return dict(term_dict)

    @classmethod
    def doc_lens(cls, postings):
        return {doc_id: len(positions) for doc_id, positions in postings.items()}

    @classmethod
    def ws_tokenizer(cls, string):
        return string.split()

    @classmethod
    def build_index_from_tokenizer(cls, array: Iterable, tokenizer=ws_tokenizer,
                                   truncate=False, batch_size=100000, avoid_copies=True) -> 'SearchArray':
        postings = defaultdict(list)
        doc_lens = {}
        term_dict = {}
        for i, string in enumerate(array):
            if truncate and i >= batch_size:
                break
            tokens = tokenizer(string)
            for token in tokens:
                postings[token].append(i)
            doc_lens[i] = len(tokens)
        return SearchArray(
            postings=posting_dict,
            doc_len=sum(doc_lens.values()) // len(doc_lens),
            posns=term_dict,
            encoded=True
        )

    @classmethod
    def index(cls, array: Iterable, tokenizer=ws_tokenizer,
              truncate=False, batch_size=100000, avoid_copies=True) -> 'SearchArray':
        if avoid_copies:
            array = islice(array, batch_size)
        return cls.build_index_from_tokenizer(array, tokenizer, truncate, batch_size, avoid_copies)
